#!/usr/bin/env python3
"""Build the specialist ecosystem research graph from reviewable, compact source data."""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
AS_OF = "2026-08-25"


def write_jsonl(name: str, rows: list[dict]) -> None:
    with (ROOT / name).open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n")


def source(sid, title, publisher, kind, url, date, scope, supports, limitations=None, currentness="current"):
    return {
        "source_id": f"source.{sid}",
        "title": title,
        "publisher": publisher,
        "source_kind": kind,
        "url": url,
        "published_or_released": date,
        "accessed_at": AS_OF,
        "authority_scope": scope,
        "supports": supports,
        "limitations": limitations or ["Does not establish universal effectiveness or complete market coverage."],
        "currentness": currentness,
    }


