def company(
    cid,
    name,
    categories,
    source_refs,
    practices,
    capabilities,
    products,
    verticals,
    industries,
    *,
    purity="core_specialist",
    llm="separable",
    quarantined=None,
    delivery=None,
    ip=None,
    dependencies=None,
    geo=None,
    status="operating",
    independence="independent",
    parent=None,
    scope="organization",
    confidence="medium",
):
    evidence = [f"source.{ref}" for ref in source_refs]
    state = "artifact_verified" if any(
        token in source_refs
        for token in ("gurobi_docs", "ampl", "aimms", "timefold", "ortools_mathopt", "jump_1", "cuopt_repo", "scip_home", "cube", "soda", "great_expectations", "elementary", "growthbook", "fluxicon", "celonis_ocpm")
    ) else "vendor_claim"
    return {
        "company_id": f"company.{cid}",
        "name": name,
        "record_scope": scope,
        "categories": categories,
        "operating_status": status,
        "current_as_of": AS_OF,
        "ownership": {"independence": independence, "parent": parent},
        "purity": {
            "tier": purity,
            "primary_record_eligible": purity not in {"dependency_only", "excluded_generalist"},
            "rationale": "Inference from the cited current product/company surface: specialist analytical or decision capability is central to this record's assessed scope.",
        },
        "non_llm_core": {
            "status": llm,
            "included_capabilities": capabilities,
            "quarantined_claims": quarantined or [],
        },
        "claims": [{
            "claim_id": f"claim.{cid}.capability_surface",
            "statement": "The cited official material exposes the named non-LLM capability, product, or specialist delivery surface.",
            "state": state,
            "evidence_refs": evidence,
            "limitations": ["Feature availability does not prove comparative superiority, outcome size, or applicability outside documented cases."],
        }],
        "practice_refs": sorted(set(practices)),
        "vertical_cases": verticals,
        "products_modules": products,
        "delivery_models": delivery or ["specialist software and expert enablement"],
        "reusable_ip": ip or products,
        "dependencies": dependencies or ["customer source systems", "customer data contracts", "runtime/provider selected per deployment"],
        "geographic_scope": geo or ["multi-region or scope not fully evidenced"],
        "industry_scope": industries,
        "evidence_refs": evidence,
        "evidence_confidence": confidence,
        "limitations": [
            "Record is a bounded research candidate, not an endorsement or exhaustive capability inventory.",
            "Industry and geography lists reflect cited offering surfaces, not verified delivery in every locale or subindustry.",
        ],
        "completeness_claim": False,
    }


