def expert(eid, name, roles, contribution, artifact, source_refs, practices, learn, *, currentness="active", confidence="high", limitations=None):
    evidence = [f"source.{ref}" for ref in source_refs]
    return {
        "expert_id": f"expert.{eid}",
        "name": name,
        "current_as_of": AS_OF,
        "currentness": currentness,
        "roles": roles,
        "contributions": [{
            "contribution": contribution,
            "artifact": artifact,
            "evidence_refs": evidence,
            "limitations": limitations or ["Contribution is bounded to the cited artifact/profile; it is not a claim of sole invention or universal authority."],
        }],
        "practice_refs": sorted(set(practices)),
        "what_corpus_can_learn": learn,
        "evidence_refs": evidence,
        "evidence_confidence": confidence,
        "limitations": limitations or ["This is an artifact-based expert record, not a ranking or complete bibliography."],
        "popularity_basis": False,
        "completeness_claim": False,
    }


