def edge_rows(entity_key: str, rows: list[dict], relation: str) -> list[dict]:
    edges = []
    for row in rows:
        source_id = row[entity_key]
        evidence = row["evidence_refs"]
        for practice in row["practice_refs"]:
            slug = practice.replace("analytics.", "").replace(".", "_")
            edges.append({
                "edge_id": f"edge.{source_id}.{slug}",
                "from_id": source_id,
                "to_practice_id": practice,
                "relation": relation,
                "claim_state": "artifact_verified" if row["evidence_confidence"] == "high" else "vendor_claim",
                "evidence_refs": evidence,
                "limitations": ["Edge means evidence of contribution/offering, not exclusive ownership, effectiveness, or complete implementation of the practice."],
            })
    return edges


COMPANY_EDGES = edge_rows("company_id", COMPANIES, "offers")
EXPERT_EDGES = edge_rows("expert_id", EXPERTS, "formalized")


def main() -> None:
    write_jsonl("sources.jsonl", SOURCES)
    write_jsonl("companies.jsonl", COMPANIES)
    write_jsonl("experts.jsonl", EXPERTS)
    write_jsonl("innovations.jsonl", INNOVATIONS)
    write_jsonl("practice-company-edges.jsonl", COMPANY_EDGES)
    write_jsonl("expert-practice-edges.jsonl", EXPERT_EDGES)


if __name__ == "__main__":
    main()
